# GameState — MV core: vida, shards, habilidades, checkpoint, cinema, save
# versionado (user://save_slot_1.cfg). Consulte data/spec.json no projeto.

signal won
signal died
signal boss_hp_updated(value: int)
signal cinema(title: String)
signal cinema_end
signal parried
